mapper.update:
update mst_item_class
   set class_nm = #{f.classNm}, sort_no = #{f.sortNo}, use_yn = #{f.useYn}, remark = #{f.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where class_id = #{id} and row_ver = #{f.rowVer}

update mst_class_prop
   set prop_nm = #{f.propNm}, unit_nm = #{f.unitNm}, scale = #{f.scale}, options = cast(#{f.optionsJson} as jsonb),
       required_yn = #{f.requiredYn}, semantic_id = #{f.semanticId}, sort_no = #{f.sortNo}, use_yn = #{f.useYn},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where prop_id = #{id} and row_ver = #{f.rowVer}

choose.when:
update mst_item set item_class_id = #{classId}, attrs = cast(#{attrs} as jsonb),
                    row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where item_id = #{id} and row_ver = #{rowVer}
